import React, { useEffect } from 'react';
import './Header.css';  // Make sure to import the CSS for the Header component

const Header = () => {
    useEffect(() => {
        // Debounce function to limit the rate at which a function is executed
        const debounce = (func, wait) => {
            let timeout;
            return function executedFunction(...args) {
                const later = () => {
                    clearTimeout(timeout);
                    func(...args);
                };
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
            };
        };

        const handleScroll = debounce(() => {
            const header = document.getElementById('header');
            if (header) { // Check if the header element exists
                if (window.scrollY > 100) { // Adjust the 100px threshold as needed
                    header.classList.add('scrolled');
                } else {
                    header.classList.remove('scrolled');
                }
            }
        }, 10); // Debounce time in milliseconds

        window.addEventListener('scroll', handleScroll);

        // Cleanup function to remove the event listener
        return () => window.removeEventListener('scroll', handleScroll);
    }, []); // Empty dependency array means this effect runs once on mount

    return (
        <header id='header'>
            <nav>
                <ul>
                    <li><a href="#intro">Intro</a></li>
                    <li><a href="#about">About Me</a></li>
                    <li><a href="#skills">Skills</a></li>
                    <li><a href="#contact">Contact</a></li>
                </ul>
            </nav>
        </header>
    );
};

export default Header;
